public class MutableDateTime_addDays_TriageGen1Test {

    @Test
    public void testAddDays_Positive() {
        // Initialize with a specific date: 2023-01-01
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        dt.addDays(5);

        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(6, dt.getDayOfMonth());
        assertEquals(12, dt.getHourOfDay());
    }












}

