import static org.junit.Assert.*;

public class MutableDateTime_addDays_TriageGen1Test {











    @Test
    public void testAddDays_LeapYear() {
        // Feb 28th, 2024 (Leap year) + 1 day -> Feb 29th
        MutableDateTime dt = new MutableDateTime(2024, 2, 28, 12, 0, 0, 0);
        dt.addDays(1);

        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());

        // Feb 29th, 2024 + 1 day -> March 1st
        dt.addDays(1);
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }


}

