public class MutableDateTime_addDays_TriageGen1Test {













    @Test
    public void testAddDays_LargeValue() {
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        // Add 365 * 2 days (roughly 2 years)
        dt.addDays(730);

        // 2000 was leap, 2001 was not. 
        // 2000-01-01 + 730 days = 2002-01-01
        assertEquals(2002, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }
}
